import {SPEAKERS,conversationNode} from './conversation-model.mjs?v=breath20';
const $=id=>document.getElementById(id),dialog=$('conversation-dialog'),choices=$('conversation-choices'),KEY='elyndra-conversations-v1';let nearby=[],speaker=null,prior=null,met={};
try{const saved=JSON.parse(localStorage.getItem(KEY)||'{}');for(let key of Object.keys(SPEAKERS))met[key]=saved?.[key]===true;}catch{}
function remember(){met[speaker]=true;try{localStorage.setItem(KEY,JSON.stringify(met));}catch{}}
function context(){return {met:!!met[speaker],solved:!!window.elyndraGame?.unlocked(3),roots:!!window.elyndraGame?.unlocked(0),all:window.elyndraGame?.count()===4};}
function button(label,action){const b=document.createElement('button');b.textContent=label;b.onclick=action;choices.appendChild(b);}
function render(node='start'){const who=SPEAKERS[speaker],data=conversationNode(speaker,node,context());$('conversation-name').textContent=who.name;$('conversation-tag').textContent=who.tag;$('conversation-text').textContent=data.text;choices.replaceChildren();for(let [label,next]of data.choices)button(label,()=>{if(next==='end'){remember();dialog.close();return;}if(next==='puzzle'){remember();dialog.close();window.elyndraStartPuzzle?.(3);return;}remember();render(next);});choices.firstElementChild?.focus();}
function choose(who){speaker=who;render();}
function open(){if(!nearby.length||window.elyndraVisionOpen||document.querySelector('dialog[open]'))return;prior=document.activeElement;window.elyndraVisionOpen=true;dispatchEvent(new Event('elyndra-vision-open'));dialog.showModal();if(nearby.length===1)choose(nearby[0]);else{speaker=null;$('conversation-name').textContent='Even kennismaken';$('conversation-tag').textContent='BEWONERS VAN ELYNDRA';$('conversation-text').textContent='Wie wil je aanspreken?';choices.replaceChildren();for(let id of nearby)button(SPEAKERS[id].name,()=>choose(id));choices.firstElementChild?.focus();}}
$('talk-near').onclick=open;$('conversation-close').onclick=()=>dialog.close();dialog.addEventListener('cancel',()=>{if(speaker)remember();});dialog.addEventListener('close',()=>{if(speaker)remember();window.elyndraVisionOpen=!!document.querySelector('dialog[open]');if(!window.elyndraVisionOpen)prior?.focus();});
addEventListener('elyndra-talk-near',e=>{nearby=e.detail.filter(id=>SPEAKERS[id]);$('talk-near').hidden=!nearby.length;$('talk-near').textContent=nearby.length===1?'Praat met '+SPEAKERS[nearby[0]].name.toLowerCase()+' · T':'Even praten · T';});
addEventListener('keydown',e=>{if(e.code==='KeyT'&&!e.repeat){e.preventDefault();open();}});
